export function prepareModuleFrame(html,p){
 let base=html.replace(/href="#/g,'href="about:srcdoc#');if(!p)return base;
 base=base.replace(/font-size:(\d+(?:\.\d+)?)px/g,(_,size)=>`font-size:calc(${size}px * var(--portal-text-scale,1))`);
 const initial=JSON.stringify(p).replaceAll('<','\\u003c');
 base=base.replace("const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');","const systemReduced=window.matchMedia('(prefers-reduced-motion: reduce)');const reduced={get matches(){return window.__geoReduced??systemReduced.matches;},addEventListener(type,fn){systemReduced.addEventListener(type,fn);window.addEventListener('geodecoder:motion',fn);}};");
 base=base.replace('<script>',`<script>window.__geoReduced=${Boolean(p.reduced)};<\/script><script>`);
 const bridge=`<script>(()=>{let p=${initial};const el=id=>document.getElementById(id);let applying=false;const send=value=>{if(!applying)parent.postMessage({type:'geodecoder:module-choice',value},'*');};function apply(v){applying=true;const changed=window.__geoReduced!==v.reduced;window.__geoReduced=v.reduced;if(changed)window.dispatchEvent(new Event('geodecoder:motion'));p=v;document.documentElement.dataset.contrast=p.contrast;document.documentElement.style.setProperty('--portal-text-scale',({normal:1,large:1.25,largest:1.5})[p.text]);const labels=el('labels');if(labels&&labels.checked!==p.labels){labels.checked=p.labels;labels.dispatchEvent(new Event('change'));}const auto=el('auto-rotate'),desired=p.autoRotate&&!p.reduced;if(auto&&auto.getAttribute('aria-pressed')!==String(desired)&&!auto.disabled)auto.click();document.body.classList.toggle('portal-reduced',p.reduced);applying=false;}const css=document.createElement('style');css.textContent='@media(max-width:500px){header,.brand,.header-inner,.header-brand,.workspace-top,.stage-top,.mode-switch{flex-wrap:wrap;min-width:0;max-width:100%}.header-meta{margin-left:0}.mode-switch{display:flex}.mode-switch button{flex:1 1 auto;white-space:normal}h1,h2,h3{overflow-wrap:anywhere}}html[data-contrast=strong]{--muted:#263c52;--border:#52657e;--primary:#1747bc;--text:#132c43}body.portal-reduced *,body.portal-reduced *::before,body.portal-reduced *::after{animation:none!important;transition:none!important}';document.head.append(css);apply(p);if(p.resume)el('learn-'+p.lastSection)?.click();document.addEventListener('change',e=>{if(e.target.id==='labels')send({labels:e.target.checked});});document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(['learn-explore','learn-notes','learn-labs'].includes(b.id))send({lastSection:b.id.slice(6)});if(b.id==='auto-rotate')send({autoRotate:b.getAttribute('aria-pressed')==='true'});});window.addEventListener('message',e=>{if(e.source===parent&&e.data?.type==='geodecoder:preferences')apply(e.data.value);});})();<\/script>`;
 return base.replace('</body>',bridge+'</body>');
}
